--[=[
    @class ElementContainer
    元素容器
    注意: 元素容器是Container子类, 继承所有 Container 成员
]=]
local ElementContainer = {}
local Container = require(script.Parent.Container)
local Slot = require(script.Parent.Slot)

export type Type = typeof(ElementContainer) & Container.Type

--- @prop ElementType number
--- @within ElementContainer
--- 该容器对应的元素类型
ElementContainer.ElementType = 0

--- 获取格子列表
function ElementContainer:getSlots(): { Slot.Type } end

--- 获取容器路径
function ElementContainer:getPath() end

return ElementContainer
